11	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
12	pub enum ContributorType {
13	    Unknown,
14	    Human,
15	    Ai,
16	    Mixed,
17	}
18	
19	impl ContributorType {
20	    pub fn as_str(&self) -> &'static str {
21	        match self {
22	            Self::Unknown => "unknown",
23	            Self::Human => "human",
24	            Self::Ai => "ai",
25	            Self::Mixed => "mixed",
26	        }
27	    }
28	
29	    fn from_str(s: &str) -> Self {
30	        match s {
31	            "human" => Self::Human,
32	            "ai" => Self::Ai,
33	            "mixed" => Self::Mixed,
34	            _ => Self::Unknown,
35	        }
36	    }
37	}
