    let snapshots = store
        .get_all_snapshots(session_id)
        .unwrap_or_default();

    if snapshots.is_empty() {
        return Ok(vec![]);
    }

    let now = now_ms();
    let developer_id = whoami();
    let mut records = Vec::new();

    for (rel_path, (old_hash, _old_mtime)) in &snapshots {
        let abs_path = project_dir.join(rel_path);
        if !abs_path.exists() {
            continue;
        }

        let file_bytes = match std::fs::read(&abs_path) {
            Ok(b) => b,
            Err(_) => continue,
        };

        let current_hash = content_hash::hash_content(&file_bytes);

        if current_hash == *old_hash {
            continue;
        }

        let line_count = String::from_utf8_lossy(&file_bytes).lines().count() as u32;

        let sign_data = format!("{}:{}:{}", rel_path, current_hash, now);
        let sig = keypair.sign(sign_data.as_bytes());

        let rec = ProvenanceRecord {
