pub fn extract_model_id(hook_json: Option<&serde_json::Value>) -> String {
    if let Ok(m) = std::env::var("CLAUDE_MODEL") {
        if !m.is_empty() {
            return m;
        }
    }
    if let Some(json) = hook_json {
        if let Some(m) = json.get("model").and_then(|v| v.as_str()) {
            if !m.is_empty() {
                return m.to_string();
            }
        }
    }
    "unknown".to_string()
}

pub fn parse_diff_ranges(project_dir: &Path, rel_path: &str) -> Vec<(u32, u32)> {
    let output = Command::new("git")
        .args(["diff", "--unified=0", "HEAD", "--", rel_path])
        .current_dir(project_dir)
        .output();

    let output = match output {
        Ok(o) if o.status.success() => o,
        _ => return vec![],
    };

    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut ranges = Vec::new();

    for line in stdout.lines() {
        if !line.starts_with("@@") {
            continue;
        }
        // Parse @@ -a,b +c,d @@ format — we want the + (new file) side
        if let Some(plus_part) = line.split('+').nth(1) {
            let nums: &str = plus_part.split_whitespace().next().unwrap_or("");
            let parts: Vec<&str> = nums.split(',').collect();
            let start: u32 = parts.first().and_then(|s| s.parse().ok()).unwrap_or(1);
            let count: u32 = if parts.len() > 1 {
                parts[1].parse().unwrap_or(1)
            } else {
                1
            };
            if count > 0 {
                ranges.push((start, start + count - 1));
            }
        }
    }

    ranges
}

