// Env var tests consolidated into one to avoid thread-safety issues with set_var
#[test]
fn test_model_id_extraction() {
    // Test 1: env var takes precedence
    unsafe { std::env::set_var("CLAUDE_MODEL", "claude-opus-4") };
    assert_eq!(extract_model_id(None), "claude-opus-4");

    // Test 2: env var overrides hook JSON
    let json = serde_json::json!({"model": "from-json"});
    assert_eq!(extract_model_id(Some(&json)), "claude-opus-4");

    // Test 3: without env var, falls back to hook JSON
    unsafe { std::env::remove_var("CLAUDE_MODEL") };
    let json = serde_json::json!({"model": "claude-sonnet-4"});
    assert_eq!(extract_model_id(Some(&json)), "claude-sonnet-4");

    // Test 4: no env var, no JSON model field → "unknown"
    let json = serde_json::json!({});
    assert_eq!(extract_model_id(Some(&json)), "unknown");

    // Test 5: no env var, no JSON at all → "unknown"
    assert_eq!(extract_model_id(None), "unknown");
}

