190	fn main() {
191	    tracing_subscriber::fmt()
192	        .with_env_filter(EnvFilter::from_default_env())
193	        .with_writer(std::io::stderr)
194	        .init();
195	
196	    let cli = Cli::parse();
197	
198	    let result = match cli.command {
199	        Commands::Init { global } => hooks::install(global),
200	        Commands::Uninit { global } => hooks::uninstall(global),
201	        Commands::Wrap { command } => wrap::execute(&command),
202	        Commands::Stats { json, days, waste } => stats::show(json, days, waste),
203	        Commands::Sync { once, api_url } => {
204	            let mut config = sync::SyncConfig { one_shot: once, ..Default::default() };
205	            if let Some(url) = api_url {
206	                config.api_url = url;
207	            }
208	            sync::run(config)
209	        }
210	        Commands::Login { auth_url } => auth::login(auth_url.as_deref()),
211	        Commands::Status => auth::status(),
212	        Commands::Logout => auth::logout(),
213	        Commands::Route { command, tokens, files } => handle_route(&command, tokens, &files),
214	
215	        Commands::Blame { file, json, session, trace } => {
216	            handle_blame(&file, json, session.as_deref(), trace)
217	        }
218	        Commands::Cost { by, pr, json, days, action } => {
219	            if let Some(act) = action {
220	                match act {
221	                    CostAction::Record { session, model, input_tokens, output_tokens, cost } => {
222	                        cost_cmd::record_manual(&session, &model, input_tokens, output_tokens, cost)
223	                    }
224	                }
225	            } else {
226	                cost_cmd::show(by.as_deref(), pr.as_deref(), json, days)
227	            }
228	        }
229	        Commands::Budget { action } => match action {
230	            BudgetAction::Status { json } => budget_cmd::status(json),
231	            BudgetAction::History { days, json } => budget_cmd::history(days, json),
232	        },
233	        Commands::Cache { action } => handle_cache(action),
234	        Commands::Hook { action } => handle_hook(action),
235	        Commands::Update => {
236	            println!("codeflow {}", env!("CARGO_PKG_VERSION"));
237	            println!("commit:  {}", option_env!("CODEFLOW_GIT_SHA").unwrap_or("dev"));
238	            println!("target:  {}", env!("TARGET"));
239	            println!();
240	            println!("Update: download latest from https://github.com/codeflow-dev/codeflow/releases");
241	            Ok(())
242	        }
243	    };
244	
245	    if let Err(e) = result {
246	        tracing::error!("{:#}", e);
247	        std::process::exit(1);
248	    }
249	}
