pub fn query_by_file(&self, file_path: &str) -> Result<Vec<ProvenanceRecord>> {
    let mut stmt = self.conn.prepare(
        "SELECT id, session_id, timestamp_ms, file_path, code_hash, model_id,
                model_version, contributor_type, start_line, end_line,
                attestation_sig, developer_id, prompt_hash, project_dir
         FROM provenance_records
         WHERE file_path = ?1
         ORDER BY timestamp_ms DESC",
    )?;
    let rows = stmt
        .query_map(params![file_path], |row| {
            Ok(ProvenanceRecord {
                id: Some(row.get(0)?),
                session_id: row.get(1)?,
                timestamp_ms: row.get(2)?,
                file_path: row.get(3)?,
                code_hash: row.get(4)?,
                model_id: row.get(5)?,
                model_version: row.get(6)?,
                contributor_type: ContributorType::from_str(
                    &row.get::<_, String>(7)?,
                ),
                start_line: row.get(8)?,
                end_line: row.get(9)?,
                attestation_sig: row.get(10)?,
                developer_id: row.get(11)?,
                prompt_hash: row.get(12)?,
                project_dir: row.get(13)?,
            })
        })?
        .collect::<Result<Vec<_>, _>>()?;
    Ok(rows)
}

