// --- Pillar types (Phase 6) ---

export interface CostByPR {
  pr_ref: string;
  total_cost_usd: number;
  input_tokens: number;
  output_tokens: number;
  record_count: number;
}

export interface ProvenanceSummary {
  total_records: number;
  unique_files: number;
  unique_models: number;
  ai_percentage: number;
}

export interface BudgetSummary {
  total_spent_usd: number;
  budget_limit_usd: number;
  latest_action: string;
  policy_count: number;
}

export interface QualitySummary {
  total_findings: number;
  blocked_count: number;
  pass_rate: number;
  by_severity: Record<string, number>;
  by_check_type: Record<string, number>;
}

export function fetchCostByPR(days: number = 90): Promise<CostByPR[]> {
  return apiFetch(`/v1/cost/by-pr?days=${days}`);
}

export function fetchProvenance(days: number = 90): Promise<ProvenanceSummary> {
  return apiFetch(`/v1/provenance?days=${days}`);
}

export function fetchBudgetStatus(): Promise<BudgetSummary> {
  return apiFetch("/v1/budget/status");
}

export function fetchQualitySummary(days: number = 90): Promise<QualitySummary> {
  return apiFetch(`/v1/quality/summary?days=${days}`);
}

export async function downloadComplianceExport(
  format: string,
  days: number = 90
): Promise<void> {
  const res = await fetch(
    `${API_URL}/v1/compliance/export?format=${format}&days=${days}`,
    { headers: { "X-Tenant-ID": TENANT_ID } }
  );
  if (!res.ok) throw new Error(`Export failed: ${res.status}`);
  const blob = await res.blob();
  const ext = format === "soc2" ? "md" : "json";
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `codeflow-${format}-${new Date().toISOString().slice(0, 10)}.${ext}`;
  a.click();
  URL.revokeObjectURL(url);
}

