import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { authkitMiddleware } from "@workos-inc/authkit-nextjs";

const workosMiddleware = authkitMiddleware({
  middlewareAuth: {
    enabled: true,
    unauthenticatedPaths: ["/auth/callback"],
  },
});

export default function middleware(request: NextRequest, event: Parameters<typeof workosMiddleware>[1]) {
  if (process.env.CODEFLOW_AUTH_DISABLED === "true") {
    return NextResponse.next();
  }
  return workosMiddleware(request, event);
}

export const config = {
  matcher: [
    "/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)",
  ],
};

"use client";

import { useAuth } from "@workos-inc/authkit-nextjs/components";

export function UserNav() {
  const { user, loading } = useAuth();

  if (loading) return null;

  if (!user) {
    return (
      <div className="pt-4 border-t">
        <a
          href="/auth/callback"
          className="block px-3 py-2 text-sm text-muted-foreground hover:text-foreground"
        >
          Sign in
        </a>
      </div>
    );
  }

  return (
    <div className="pt-4 border-t space-y-1">
      <div className="px-3 py-1">
        <p className="text-sm font-medium truncate">
          {user.firstName || user.email}
        </p>
        <p className="text-xs text-muted-foreground truncate">{user.email}</p>
      </div>
      <a
        href="/auth/signout"
        className="block px-3 py-2 text-sm text-muted-foreground hover:text-foreground"
      >
        Sign out
      </a>
    </div>
  );
}

export function DemoUserNav() {
  return (
    <div className="pt-4 border-t space-y-1">
      <div className="px-3 py-1">
        <p className="text-sm font-medium truncate">Demo User</p>
        <p className="text-xs text-muted-foreground truncate">
          demo@codeflow.dev
        </p>
      </div>
      <span className="block px-3 py-1 text-xs text-amber-600 font-medium">
        Demo Mode
      </span>
    </div>
  );
}

